//! The [`Idlgen`] builder, for generating bindings from a `build.rs`.

use std::env;
use std::path::{Path, PathBuf};

use anyhow::{format_err, Context};

use crate::codegen::{self, Options};
use crate::idl::Idl;

/// Generates Rust bindings for a Solana program from its Anchor IDL.
///
/// ```no_run
/// use substreams_solana_idlgen::build::Idlgen;
///
/// fn main() -> Result<(), anyhow::Error> {
///     Idlgen::new("pumpfun", "idls/pumpfun.json")?
///         .generate()?
///         .write_to_file("src/idl/pumpfun.rs")?;
///     Ok(())
/// }
/// ```
///
/// The generated file is a module body depending only on `substreams-solana`.
/// Items that cannot be generated are reported through
/// [`GeneratedBindings::warnings`].
#[derive(Debug, Clone)]
pub struct Idlgen<'a> {
    name: String,
    idl_path: PathBuf,
    bytes: Option<&'a [u8]>,
    options: Options,
}

impl<'a> Idlgen<'a> {
    /// Creates a builder for program `name` from the IDL at `path`, relative to
    /// the crate root.
    pub fn new<S: AsRef<str>>(name: S, path: S) -> Result<Self, anyhow::Error> {
        let path = normalize_path(path.as_ref()).context("normalize path")?;
        Ok(Self {
            name: name.as_ref().to_string(),
            idl_path: path,
            bytes: None,
            options: Options::default(),
        })
    }

    /// Creates a builder for the program `name` from the IDL JSON `bytes`.
    pub fn from_bytes<S: AsRef<str>>(name: S, bytes: &'a [u8]) -> Result<Self, anyhow::Error> {
        Ok(Self {
            name: name.as_ref().to_string(),
            idl_path: PathBuf::new(),
            bytes: Some(bytes),
            options: Options::default(),
        })
    }

    /// Sets the base58 program address. Required when the IDL has none;
    /// overrides it otherwise.
    pub fn program_id<S: AsRef<str>>(mut self, address: S) -> Self {
        self.options.program_id = Some(address.as_ref().to_string());
        self
    }

    /// Generates the bindings.
    pub fn generate(&self) -> Result<GeneratedBindings, anyhow::Error> {
        let idl = match self.bytes {
            Some(bytes) => {
                let json = std::str::from_utf8(bytes).context("IDL is not UTF-8")?;
                Idl::from_json(json)
            }
            None => Idl::from_path(&self.idl_path),
        }
        .map_err(|err| format_err!("reading the IDL of `{}`: {err}", self.name))?;

        let output = codegen::generate(&idl, &self.options)
            .map_err(|err| format_err!("generating bindings for `{}`: {err}", self.name))?;
        let warnings: Vec<String> = output
            .warnings
            .iter()
            .map(|warning| format!("idlgen `{}`: {warning}", self.name))
            .collect();
        for warning in &warnings {
            println!("cargo:warning={warning}");
        }
        let file = syn::parse2::<syn::File>(output.tokens).context("parsing generated code")?;

        let code = [
            "// @generated",
            "// This file was @generated by `substreams-solana-idlgen`. Do not edit it by hand.",
            "",
        ]
        .into_iter()
        .map(str::to_string)
        .chain(prettyplease::unparse(&file).lines().map(str::to_string))
        .collect::<Vec<_>>()
        .join("\n")
            + "\n";

        Ok(GeneratedBindings { code, warnings })
    }
}

/// Generated bindings, ready to be written to a file.
pub struct GeneratedBindings {
    code: String,
    warnings: Vec<String>,
}

impl GeneratedBindings {
    /// The generated Rust code.
    pub fn code(&self) -> &str {
        &self.code
    }

    /// Items that could not be generated. Each is also printed as a
    /// `cargo:warning`.
    pub fn warnings(&self) -> &[String] {
        &self.warnings
    }

    /// Writes the code to `path`, relative to the crate root. An up-to-date file
    /// is left untouched so it does not trigger rebuilds.
    pub fn write_to_file<P: AsRef<Path>>(&self, path: P) -> Result<(), anyhow::Error> {
        let full = normalize_path(path.as_ref()).context("normalize path")?;
        if let Some(parent) = full.parent() {
            std::fs::create_dir_all(parent)
                .with_context(|| format!("creating directories for {}", parent.display()))?;
        }
        if std::fs::read(&full).is_ok_and(|current| current == self.code.as_bytes()) {
            return Ok(());
        }
        std::fs::write(&full, &self.code)
            .with_context(|| format!("writing file {}", path.as_ref().display()))
    }
}

/// `relative_path` resolved against the crate being built.
fn normalize_path<S: AsRef<Path>>(relative_path: S) -> Result<PathBuf, anyhow::Error> {
    // Workaround for https://github.com/rust-lang/rust/issues/43860.
    let cargo_toml_directory =
        env::var("CARGO_MANIFEST_DIR").map_err(|_| format_err!("Cannot find manifest file"))?;
    let mut path: PathBuf = cargo_toml_directory.into();
    path.push(relative_path);
    Ok(path)
}
